package com.spinfit.bike.ui;
import android.Manifest;import android.app.*;import android.bluetooth.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.view.*;import android.widget.*;
import com.spinfit.bike.app.*;import com.spinfit.bike.ble.*;import java.util.*;
public final class ScanActivity extends Activity implements BikeSession.StateListener{
 private final Handler h=new Handler();private LinearLayout devices;private TextView status,current,empty;private Button scan,done,disconnect;private BleBike.Scanner scanner;private final Set<String> seen=new HashSet<>();private boolean scanning,connecting,ready;
 private final Runnable timeout=()->stopScan();
 @Override protected void onCreate(Bundle b){super.onCreate(b);BikeSession.get().init(this);BikeSession.get().addStateListener(this);LinearLayout root=Ui.root(this);root.addView(Ui.topBar(this,"连接单车",this::finish));Button hr=Ui.button(this,"连接 Apple Watch / 心率设备  →",Ui.CARD,Ui.TEXT);hr.setOnClickListener(v->startActivity(new Intent(this,HeartRateActivity.class)));Ui.add(this,root,hr,20);root.addView(Ui.eyebrow(this,"LET’S GET CONNECTED"));root.addView(Ui.title(this,"下一骑，从连接开始。"));root.addView(Ui.sub(this,"打开单车电源，轻踩踏板唤醒蓝牙。\n请先退出其他正在连接单车的应用。"));Ui.gap(this,root,24);
  LinearLayout device=Ui.card(this);device.addView(new Visuals.Icon(this,"bluetooth",Ui.ACCENT),new LinearLayout.LayoutParams(Ui.dp(this,36),Ui.dp(this,36)));Ui.gap(this,device,16);current=Ui.tv(this,"尚未连接",20,Ui.TEXT,true);device.addView(current);Ui.gap(this,device,8);status=Ui.sub(this,"准备扫描附近的单车");device.addView(status);Ui.gap(this,device,20);scan=Ui.primary(this,"搜索附近单车");scan.setOnClickListener(v->{if(scanning)stopScan();else ensureScan();});device.addView(scan);Ui.gap(this,device,10);disconnect=Ui.button(this,"断开当前单车",Ui.CARD2,Ui.TEXT);disconnect.setVisibility(BikeSession.get().isConnected()?View.VISIBLE:View.GONE);disconnect.setOnClickListener(v->{if(BikeSession.get().active()){Ui.dialog(this,"训练正在进行","结束当前训练后，可以断开单车。");return;}BikeSession.get().disconnect();refreshCurrent();});device.addView(disconnect);Settings settings=new Settings(this);if(!settings.bikeAddress().isEmpty()){Ui.gap(this,device,12);Button reconnect=Ui.button(this,"重新连接 "+settings.bikeName(),Ui.CARD2,Ui.TEXT);reconnect.setOnClickListener(v->{if(hasPermission())connect(settings.bikeName(),settings.bikeAddress(),settings.bikeType());else ensureScan();});device.addView(reconnect);}Ui.add(this,root,device,0);
  root.addView(Ui.section(this,"附近的单车",null,null));devices=Ui.col(this);empty=Ui.sub(this,"搜索到的单车会显示在这里");devices.addView(empty);root.addView(devices);Ui.gap(this,root,24);
  done=Ui.primary(this,"已连接，返回开始骑行  →");done.setOnClickListener(v->finish());done.setVisibility(BikeSession.get().isConnected()?View.VISIBLE:View.GONE);Ui.add(this,root,done,16);
  Button demo=Ui.button(this,"没有单车？体验演示模式",Ui.CARD,Ui.DIM);demo.setOnClickListener(v->{if(BikeSession.get().active()){Ui.dialog(this,"训练正在进行","请先结束当前训练，再切换单车。");return;}stopScan();BikeSession.get().connectDemo();});root.addView(demo);Ui.gap(this,root,12);Button diagnostic=Ui.button(this,"连接帮助与诊断",Ui.BG,Ui.DIM);diagnostic.setOnClickListener(v->{String info=BikeSession.get().source()==null?"请确认蓝牙已开启、权限已允许，并踩动踏板唤醒单车。部分机型还需打开系统定位。\n\n如单车被其他 APP 占用，请先退出该 APP。":BikeSession.get().source().diagnostics();StringBuilder logs=new StringBuilder(info);List<String> lines=BikeSession.get().logs();for(int i=Math.max(0,lines.size()-12);i<lines.size();i++)logs.append("\n").append(lines.get(i));Ui.dialog(this,"连接帮助与诊断",logs.toString());});root.addView(diagnostic);Ui.screen(this,root,null);refreshCurrent();}
 private boolean hasPermission(){if(Build.VERSION.SDK_INT<23)return true;if(Build.VERSION.SDK_INT>=31)return checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED;return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 private void ensureScan(){if(BikeSession.get().active()){Ui.dialog(this,"训练正在进行","请先结束当前训练，再切换单车。");return;}if(!hasPermission()){requestPermissions(Build.VERSION.SDK_INT>=31?new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT}:new String[]{Manifest.permission.ACCESS_FINE_LOCATION},11);return;}startScan();}
 @Override public void onRequestPermissionsResult(int r,String[] ps,int[] gr){super.onRequestPermissionsResult(r,ps,gr);if(hasPermission())startScan();else{status.setText("蓝牙权限未允许，请在系统设置中开启后重试");scan.setText("重新授权并搜索");}}
 private void startScan(){BluetoothManager manager=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);BluetoothAdapter adapter=manager==null?null:manager.getAdapter();if(adapter==null){status.setText("这台设备不支持蓝牙");return;}if(!adapter.isEnabled()){status.setText("请先打开手机蓝牙");try{startActivity(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE));}catch(Exception e){}return;}stopScan();seen.clear();devices.removeAllViews();empty=Ui.sub(this,"正在搜索，请保持单车唤醒…");devices.addView(empty);scanning=true;scan.setText("停止搜索");status.setText("正在搜索附近的单车 · 最多 15 秒");scanner=new BleBike.Scanner(adapter,new BleBike.Scanner.Callback(){public void onDevice(String n,String addr,int r,byte[] rec){runOnUiThread(()->add(n,addr,r));}public void onError(String msg){runOnUiThread(()->{stopScan();status.setText(msg);});}});scanner.start();h.postDelayed(timeout,15000);}
 private void stopScan(){h.removeCallbacks(timeout);if(scanner!=null)scanner.stop();scanner=null;if(scanning){scanning=false;scan.setText("重新搜索");status.setText(seen.isEmpty()?"未发现单车，请踩动踏板后重新搜索":"搜索完成，选择你的单车连接");if(empty!=null)empty.setText(seen.isEmpty()?"暂未找到设备 · 请确认单车已唤醒":"");}}
 private void add(String name,String address,int rssi){if(!scanning||!seen.add(address))return;if(devices.indexOfChild(empty)>=0)devices.removeView(empty);LinearLayout c=Ui.card(this);LinearLayout r=Ui.row(this);LinearLayout t=Ui.col(this);t.addView(Ui.tv(this,name,17,Ui.TEXT,true));Ui.gap(this,t,7);t.addView(Ui.sub(this,rssi>-65?"信号良好":"信号较弱 · 靠近单车"));Ui.gap(this,t,4);t.addView(Ui.tv(this,address,11,Ui.DIM,false));Ui.weight(r,t);Button b=Ui.button(this,"连接",Ui.ACCENT,Ui.INK);b.setOnClickListener(v->connect(name,address,BikeSource.TYPE_FTMS));r.addView(b);c.addView(r);Ui.add(this,devices,c,12);}
 private void connect(String name,String address,int type){if(BikeSession.get().active())return;stopScan();connecting=true;scan.setEnabled(false);status.setText("正在连接 "+name+"…");BikeSession.get().connectBle(this,address,name,type);h.postDelayed(()->{if(connecting&&!BikeSession.get().isConnected()){connecting=false;scan.setEnabled(true);status.setText("连接超时，请确认单车未被占用后重试");}},15000);}
 private void refreshCurrent(){BikeSession s=BikeSession.get();current.setText(s.isConnected()?s.deviceName():"尚未连接");done.setVisibility(s.isConnected()?View.VISIBLE:View.GONE);disconnect.setVisibility(s.isConnected()?View.VISIBLE:View.GONE);if(s.isConnected())status.setText(s.isDemo()?"演示模式 · 全部为模拟数据":"已连接，踩动踏板即可同步训练数据");}
 @Override public void onState(int state,String message){if(state<0||state>=20)return;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;status.setText(message);if(state==BikeSource.STATE_CONNECTED||state==BikeSource.STATE_ERROR||state==BikeSource.STATE_DISCONNECTED){connecting=false;scan.setEnabled(true);}refreshCurrent();});}
 @Override protected void onDestroy(){stopScan();h.removeCallbacksAndMessages(null);BikeSession.get().removeStateListener(this);super.onDestroy();}
}
